      SUBROUTINE RTORSHCC     TRANSFERS MATRIX R TO RSHCC ----------------------------------------------------------------------      INCLUDE 'ELM17A.CIN'      INCLUDE 'R.CIN'      INCLUDE 'RC3.CIN'      INCLUDE 'T.CIN'      INCLUDE 'TC3.CIN'      INCLUDE 'U.CIN'      INCLUDE 'UC3.CIN'C      DO 10 JK = 1, 36   10 RSHL(JK) = RL(JK)      IF (NORD1 .GE. 2) THEN        DO 20 JKM = 1, 105   20   TSHL(JKM) = TL(JKM)      ENDIF      IF (NORD1 .GE. 3) THEN        DO 30 JKLM = 1, 280   30   USHL(JKLM) = UL(JKLM)      ENDIF      RETURN      END